using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.USR.RazasMascota{    [SwaggerSchema("Modelo de lectura de un RazasMascota")]    [GraphQLDescription("Objeto que representa un RazasMascota existente.")]    public class clReadRazasMascota    {        [SwaggerSchema("Identificador único del RazasMascota")]        [GraphQLDescription("Identificador único del RazasMascota")]        public int? RazaMascotaID { get; set; }        [SwaggerSchema("TipoMascotaID")]        [GraphQLDescription("TipoMascotaID")]        public int? TipoMascotaID { get; set; }        [SwaggerSchema("RazaMascota")]        [GraphQLDescription("RazaMascota")]        public string? RazaMascota { get; set; } = default!;        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un RazasMascota")]    [GraphQLDescription("Input para crear un RazasMascota.")]    public class clCreateRazasMascota    {        [GraphQLNonNullType] [SwaggerSchema("TipoMascotaID")]        [GraphQLDescription("TipoMascotaID")]        public int TipoMascotaID { get; set; }        [GraphQLNonNullType] [SwaggerSchema("RazaMascota")]        [GraphQLDescription("RazaMascota")]        public string RazaMascota { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un RazasMascota")]    [GraphQLDescription("Input para actualizar parcialmente un RazasMascota.")]    public class clUpdateRazasMascota    {        [SwaggerSchema("Identificador único del RazasMascota")]        [GraphQLDescription("Identificador único del RazasMascota")]        public int? RazaMascotaID { get; set; }        [SwaggerSchema("TipoMascotaID")]        [GraphQLDescription("TipoMascotaID")]        public int? TipoMascotaID { get; set; }        [SwaggerSchema("RazaMascota")]        [GraphQLDescription("RazaMascota")]        public string? RazaMascota { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}